def transform(grid):
    """Recolor alternating connected objects, starting at the rightmost."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append(cells)
    objects.sort(key=lambda cells: (min(c for _, c in cells), min(r for r, _ in cells)))
    out = [row[:] for row in grid]
    for i in range(len(objects) - 1, -1, -2):
        for r, c in objects[i]:
            out[r][c] = 8
    return out
